import cellxgene_census, collections, time
with cellxgene_census.open_soma() as census:
    obs=census['census_data']['homo_sapiens'].obs
    counts={}
    t=time.time(); batches=0
    reader=obs.read(column_names=['dataset_id','donor_id'])
    for tbl in reader:
        df=tbl.to_pandas()
        g=df.groupby('dataset_id').agg(n_cells=('donor_id','size'))
        for dsid,row in g.iterrows():
            if dsid not in counts:
                counts[dsid]=[0,set()]
            counts[dsid][0]+=int(row.n_cells)
